import type { Page, Locator, FrameLocator } from "playwright";

/**
 * SharePoint / Microsoft 365 / Excel Online selector registry.
 *
 * Covers the three distinct auth/UI layers the "Download onboarding
 * spreadsheet" dashboard button has to traverse:
 *
 *   1. Microsoft AAD login (login.microsoftonline.com) — email prefill step
 *      before UCSD Shibboleth SSO hands off.
 *   2. Post-Duo KMSI ("Stay signed in?") interstitial on login.srf.
 *   3. Excel Online viewer (ucsdcloud-my.sharepoint.com/.../doc2.aspx) which
 *      wraps the ribbon / workbook inside `iframe[name="WacFrame_Excel_0"]`.
 *
 * UCSD Shibboleth username/password and Duo polling live in
 * `src/infra/auth/sso-fields.ts` + `src/infra/auth/duo-poll.ts` and are shared with every
 * other system, so they're intentionally NOT duplicated here. Call sites
 * should compose:
 *
 *   microsoft.emailInput / microsoft.nextButton
 *     → fillSsoCredentials + clickSsoSubmit
 *     → pollDuoApproval({ systemLabel: "SharePoint", ... })
 *     → kmsi.noButton
 *     → excelOnline.getFrame + file.* + copyFlyout.*
 *
 * Verified end-to-end on 2026-04-22 via playwright-cli against the
 * ApplicantByProposedStartDate workbook at ucsdcloud-my.sharepoint.com.
 */

// ─── Microsoft AAD login (email prefill step) ───────────────────────────────

export const microsoft = {
  /**
   * Email textbox on the Microsoft sign-in page. Primary is the CSS fallback
   * (`input[name="loginfmt"]` / `input[type="email"]`) because the
   * accessible name varies by tenant ("Enter your email, phone, or Skype.").
   * verified 2026-04-22
   * @tags microsoft, login, email, textbox
   */
  emailInput: (page: Page): Locator =>
    page
      .locator('input[type="email"]')
      .or(page.locator('input[name="loginfmt"]')),

  /**
   * "Next" button on the Microsoft email step. Falls back to a generic submit
   * input since some tenants render the button as `<input type="submit">`.
   * verified 2026-04-22
   * @tags microsoft, login, next, button
   */
  nextButton: (page: Page): Locator =>
    page
      .getByRole("button", { name: /^next$/i })
      .or(page.locator('input[type="submit"][value*="Next" i]'))
      .or(page.locator('input[type="submit"]')),
};

// ─── UCSD ADFS federation login (`ad-wfs-aws.ucsd.edu/adfs/ls/`) ───────────
//
// For SharePoint / OneDrive, UCSD federates Microsoft AAD through an ADFS
// endpoint (`ad-wfs-aws.ucsd.edu`) instead of the Shibboleth IdP at
// `a5.ucsd.edu` used by UCPath / CRM / Kuali. The form is visually simpler:
// a pre-populated "User Account" textbox (Microsoft passes the email through
// on the URL), a "Password" textbox, and a "Sign in" button. After submit it
// hands off to the normal Duo frame — the same `pollDuoApproval` /
// `requestDuoApproval` helpers work against it unchanged.
//
// Field names (`UserName` / `Password` / `#submitButton`) are stable ADFS
// defaults and are reused across every UC federated ADFS tenant, so the
// primary selectors below are safe.

export const adfs = {
  /**
   * "User Account" textbox on the ADFS sign-in page. Usually pre-populated
   * by Microsoft via the `?username=` URL parameter; we still explicitly
   * re-fill it defensively in case the hand-off ever misses. Primary is the
   * stable name attribute; fallbacks are the DOM id and the accessible name.
   * verified 2026-04-22
   * @tags adfs, ucsd, sharepoint, username, textbox, login
   */
  usernameInput: (page: Page): Locator =>
    page
      .locator('input[name="UserName"]')
      .or(page.locator("#userNameInput"))
      .or(page.getByRole("textbox", { name: /User Account/i })),

  /**
   * "Password" textbox on the ADFS sign-in page.
   * verified 2026-04-22
   * @tags adfs, ucsd, sharepoint, password, textbox, login
   */
  passwordInput: (page: Page): Locator =>
    page
      .locator('input[name="Password"]')
      .or(page.locator("#passwordInput"))
      .or(page.getByRole("textbox", { name: /^password$/i })),

  /**
   * "Sign in" submit button on the ADFS sign-in page.
   * verified 2026-04-22
   * @tags adfs, ucsd, sharepoint, submit, sign-in, button, login
   */
  submitButton: (page: Page): Locator =>
    page
      .locator("#submitButton")
      .or(page.getByRole("button", { name: /^sign in$/i })),
};

// ─── "Keep me signed in?" (KMSI) interstitial — post-Duo ────────────────────

export const kmsi = {
  /**
   * "No" button on the "Stay signed in?" / KMSI prompt (login.srf). We always
   * click No so the persistent context decides what to remember, not AAD.
   * verified 2026-04-22
   * @tags microsoft, kmsi, stay-signed-in, no, button
   */
  noButton: (page: Page): Locator =>
    page
      .getByRole("button", { name: /^no$/i })
      .or(page.locator('input[type="button"][value="No"]'))
      .or(page.locator('input[type="submit"][value="No"]')),
};

// ─── Excel Online viewer (everything below is inside the WAC iframe) ───────

/**
 * Returns the Excel Online FrameLocator. The ribbon, file menu, and workbook
 * body all live inside `iframe[name="WacFrame_Excel_0"]` on doc2.aspx — every
 * post-auth interaction MUST go through this frame or selectors resolve to
 * nothing. verified 2026-04-22
 * @tags excel, iframe, frame, wac
 */
export function getExcelFrame(page: Page): FrameLocator {
  return page.frameLocator('iframe[name="WacFrame_Excel_0"]');
}

export const excelOnline = {
  /**
   * File button on the Excel Online ribbon (opens the backstage menu).
   * `exact: true` avoids matching "File menu", "File tab", etc.
   * verified 2026-04-22
   * @tags excel, ribbon, file, button
   */
  fileButton: (f: FrameLocator): Locator =>
    f.getByRole("button", { name: "File", exact: true }),
};

// ─── File menu (backstage) → Create a Copy → Download a Copy ──────────────

export const fileMenu = {
  /**
   * "Create a Copy" menuitem in the File backstage. Must be HOVERED (not
   * clicked) to open the submenu containing "Download a Copy". Clicking
   * navigates to "Create a copy online" instead.
   * verified 2026-04-22
   * @tags excel, file-menu, create-a-copy, menuitem, backstage
   */
  createACopy: (f: FrameLocator): Locator =>
    f.getByRole("menuitem", { name: "Create a Copy" }),

  /**
   * "Download a Copy" menuitem — in the "Create a Copy" flyout. THIS is the
   * xlsx download path. Triggering it fires the browser's `download` event.
   * verified 2026-04-22
   * @tags excel, file-menu, download, xlsx, workbook, menuitem
   */
  downloadACopy: (f: FrameLocator): Locator =>
    f.getByRole("menuitem", { name: "Download a Copy" }),
};

visionProvider.text:
/**
 * Free-tier capability + limit config for the vision-OCR pool.
 *
 * Everything here is FREE-TIER and best-effort: the published RPM/TPM/RPD
 * numbers shift and several providers don't document them at all, so these
 * seed the *proactive* usage gate (usage-tracker.ts) and are then corrected at
 * runtime by the real `x-ratelimit-*` / `Retry-After` / RetryInfo headers each
 * response carries. Treat the table as a starting estimate, not ground truth.
 *
 * `imgTokens` is the measured prompt-token cost of one ~A4 page image for that
 * model (from scripts/ocr/probe-vision.ts, 2026-06-02) — used to pre-check TPM
 * before the real `usage.prompt_tokens` comes back.
 *
 * Limits are *per model* because free quotas are enforced per model: one Gemini
 * key exhausted on gemini-2.5-flash can still call gemini-2.5-flash-lite. That
 * per-model headroom is the main free-tier multiplier, so the pool walks a
 * model fallback chain per key before moving to the next key.
 *
 * Every default is overridable by env:
 *   OCR_<PROVIDER>_MODELS   comma-separated model chain (first = primary)
 *   e.g. OCR_GEMINI_MODELS="gemini-2.5-flash,gemini-2.5-flash-lite"
 */

export type VisionProviderId = "gemini" | "groq" | "mistral" | "sambanova" | "openrouter";

export interface ModelLimit {
  /** Requests per minute (per key, free tier). */
  rpm: number;
  /** Tokens per minute (per key, free tier). */
  tpm: number;
  /** Requests per day (per key/model, free tier). 0 = no known daily cap. */
  rpd: number;
  /** Measured prompt-token cost of one page image (probe-vision.ts). */
  imgTokens: number;
}

export interface ModelSpec {
  id: string;
  limit: ModelLimit;
  /**
   * Accuracy tier for handwritten extraction. 1 = trusted on hard
   * handwriting; 2 = throughput overflow — observed mangling names/digits
   * (live 2026-06-11: ministral-8b read "Barahona Martell" as "Merrell",
   * llama-4-scout produced "Marbell"/"Mian", nemotron "Barbhane Martelli",
   * gemini-2.5-flash-lite "Juun"). Tier 2 cells are only picked when no
   * tier-1 cell has headroom, and are excluded from second-opinion re-OCR.
   *
   * **Tier 1 is a CORRECTNESS claim, not a speed one, and it must be EARNED by
   * measurement — never by reputation or recency of the model.** The bar is not
   * "reads well"; it is "does not INVENT". A model that emits a confident,
   * plausible SSN for handwriting it cannot actually read is worse than one that
   * returns nothing: UCPath answers "no results" for the invented digits, and a
   * real employee is reported to the operator as a stranger — indistinguishable
   * from a true absence (see `forms/i9.ts`, the 2026-07-13 batch where 17 of 29
   * Section 1s were misread and every verdict shipped as confident).
   *
   * Before promoting ANY model to tier 1, score it page-by-page against
   * hand-read paper truth on real scans and count FABRICATIONS separately from
   * misses (a decline is safe; an invention is not). The 2026-07-14 pass
   * demoted `gemini-2.5-flash` and `mistral-medium-latest` on exactly that
   * evidence, and `extractedBy` on each record exists so this stays measurable.
   */
  tier: 1 | 2;
  /** Tier 1 is allowed only after paper-truth accuracy/fabrication scoring. */
  trust: "benchmarked" | "unbenchmarked";
}

export interface ProviderConfig {
  id: VisionProviderId;
  /** Lower = preferred when several keys/models have capacity. */
  priority: number;
  /** OpenAI-compatible chat endpoint (undefined for Gemini's native SDK path). */
  endpoint?: string;
  /** Whether to send response_format:{type:"json_object"}. */
  jsonMode: boolean;
  /** Env var prefix for keys (GEMINI_API_KEY, GEMINI_API_KEY2, …). */
  keyEnvPrefix: string;
  /** Env var holding a comma-separated model chain override. */
  modelsEnvVar: string;
  /** Default model fallback chain (first = primary). */
  models: ModelSpec[];
}

// ── Per-model free-tier limits (best-effort; see file header) ────────────────

const GEMINI_FLASH_RPD = 250; // GA flash & preview models: ~250 RPD free.
const GEMINI_LITE_RPD = 1000; // flash-lite class: higher daily allowance.
const GEMINI_TPM = 250_000;

const GEMINI_MODELS: ModelSpec[] = [
  // DEMOTED to tier 2 on 2026-07-14. Benchmarked against hand-read paper truth
  // on 8 scanned I-9 Section 1s: name 2/8, dob 1/8, ssn 1/8 — and, worse, it
  // FABRICATED a date of birth AND an SSN on a page whose handwriting is
  // genuinely illegible, while reporting `illegible: []`. It ignores the
  // prompt's accuracy rule. A model that invents a plausible SSN is not a weak
  // model, it is a dangerous one: UCPath answers "no results" for the invented
  // digits and the operator is told a real employee does not work here.
  { id: "gemini-2.5-flash", limit: { rpm: 10, tpm: GEMINI_TPM, rpd: GEMINI_FLASH_RPD, imgTokens: 1100 }, tier: 2, trust: "benchmarked" },
  // Strongest reader in the 2026-07-14 benchmark: name 8/8, dob 8/8, ssn 7/8.
  { id: "gemini-3-flash-preview", limit: { rpm: 10, tpm: GEMINI_TPM, rpd: GEMINI_FLASH_RPD, imgTokens: 1125 }, tier: 1, trust: "benchmarked" },
  // Overflow: cheaper tokens + higher daily cap; weaker on hard handwriting.
  { id: "gemini-2.5-flash-lite", limit: { rpm: 15, tpm: GEMINI_TPM, rpd: GEMINI_LITE_RPD, imgTokens: 300 }, tier: 2, trust: "unbenchmarked" },
  { id: "gemini-3.1-flash-lite", limit: { rpm: 15, tpm: GEMINI_TPM, rpd: GEMINI_LITE_RPD, imgTokens: 1125 }, tier: 2, trust: "unbenchmarked" },
  // Safest reader in the 2026-07-14 benchmark: 7/8 on every field and the ONLY
  // model that never fabricated — it correctly returned null + `illegible` on
  // the unreadable page. Declining to answer is the behaviour we want.
  { id: "gemini-3.5-flash", limit: { rpm: 10, tpm: GEMINI_TPM, rpd: GEMINI_FLASH_RPD, imgTokens: 1125 }, tier: 1, trust: "benchmarked" },
];

// Groq: org-level limits, single vision model. ~30 RPM / 30k TPM / 1000 RPD free.
const GROQ_MODELS: ModelSpec[] = [
  { id: "meta-llama/llama-4-scout-17b-16e-instruct", limit: { rpm: 30, tpm: 30_000, rpd: 1000, imgTokens: 2400 }, tier: 2, trust: "unbenchmarked" },
];

// Mistral: free tier not published (≈1 RPS, 1B tok/month). Conservative caps.
const MISTRAL_MODELS: ModelSpec[] = [
  // DEMOTED to tier 2 on 2026-07-14. Same benchmark: it reproduced the exact
  // real-world misreads that started this ("Miralik" for "Mihalik", "Kim" for
  // "Kimi", 902-30-6130 for 909-35-2296, 992-52-1840 for 945-27-0329), it
  // fabricated a DOB on the illegible page, and it even corrupted the SECTION 2
  // cross-check number itself — poisoning the very oracle we use to catch bad
  // reads. Handwritten boxed digits are its weak spot (0/6, 9/4, 8/9).
  { id: "mistral-medium-latest", limit: { rpm: 30, tpm: 500_000, rpd: 2000, imgTokens: 1618 }, tier: 2, trust: "benchmarked" },
  { id: "ministral-8b-latest", limit: { rpm: 30, tpm: 500_000, rpd: 2000, imgTokens: 1618 }, tier: 2, trust: "unbenchmarked" },
  { id: "mistral-small-latest", limit: { rpm: 30, tpm: 500_000, rpd: 2000, imgTokens: 1618 }, tier: 2, trust: "unbenchmarked" },
];

// SambaNova: free RPD is brutally low (~20/day) — last-resort overflow only.
const SAMBANOVA_MODELS: ModelSpec[] = [
  { id: "Llama-4-Maverick-17B-128E-Instruct", limit: { rpm: 20, tpm: 200_000, rpd: 20, imgTokens: 2400 }, tier: 2, trust: "unbenchmarked" },
  { id: "gemma-4-31B-it", limit: { rpm: 20, tpm: 200_000, rpd: 20, imgTokens: 355 }, tier: 2, trust: "unbenchmarked" },
  { id: "gemma-3-12b-it", limit: { rpm: 20, tpm: 200_000, rpd: 20, imgTokens: 1100 }, tier: 2, trust: "unbenchmarked" },
];

// OpenRouter: per-account global ~20 RPM / 50 RPD free (1000 RPD after $10 credit).
// Free vision models (`:free`) confirmed working via probe-vision.ts.
const OPENROUTER_MODELS: ModelSpec[] = [
  { id: "google/gemma-4-31b-it:free", limit: { rpm: 20, tpm: 200_000, rpd: 50, imgTokens: 284 }, tier: 2, trust: "unbenchmarked" },
  { id: "google/gemma-4-26b-a4b-it:free", limit: { rpm: 20, tpm: 200_000, rpd: 50, imgTokens: 284 }, tier: 2, trust: "unbenchmarked" },
  { id: "nvidia/nemotron-3-nano-omni-30b-a3b-reasoning:free", limit: { rpm: 20, tpm: 200_000, rpd: 50, imgTokens: 1214 }, tier: 2, trust: "unbenchmarked" },
];

const PROVIDERS: ProviderConfig[] = [
  {
    id: "gemini",
    priority: 1,
    jsonMode: true,
    keyEnvPrefix: "GEMINI_API_KEY",
    modelsEnvVar: "OCR_GEMINI_MODELS",
    models: GEMINI_MODELS,
  },
  {
    id: "groq",
    priority: 2,
    endpoint: "https://api.groq.com/openai/v1/chat/completions",
    jsonMode: false,
    keyEnvPrefix: "GROQ_API_KEY",
    modelsEnvVar: "OCR_GROQ_MODELS",
    models: GROQ_MODELS,
  },
  {
    id: "mistral",
    priority: 3,
    endpoint: "https://api.mistral.ai/v1/chat/completions",
    jsonMode: true,
    keyEnvPrefix: "MISTRAL_API_KEY",
    modelsEnvVar: "OCR_MISTRAL_MODELS",
    models: MISTRAL_MODELS,
  },
  {
    id: "openrouter",
    priority: 4,
    endpoint: "https://openrouter.ai/api/v1/chat/completions",
    jsonMode: false,
    keyEnvPrefix: "OPEN_ROUTER_API_KEY",
    modelsEnvVar: "OCR_OPENROUTER_MODELS",
    models: OPENROUTER_MODELS,
  },
  {
    id: "sambanova",
    priority: 5,
    endpoint: "https://api.sambanova.ai/v1/chat/completions",
    jsonMode: true,
    keyEnvPrefix: "SAMBANOVA_API_KEY",
    modelsEnvVar: "OCR_SAMBANOVA_MODELS",
    models: SAMBANOVA_MODELS,
  },
];

/** Default per-page image-token estimate when a model isn't in the table. */
export const DEFAULT_IMG_TOKENS = 1500;

/**
 * Resolve a provider's model chain, honoring the legacy single-model env vars
 * (OCR_GEMINI_MODEL, …) and the new comma-list (OCR_GEMINI_MODELS). The
 * single-model var, if set, is prepended as the primary (back-compat).
 */
export function resolveModelChain(cfg: ProviderConfig): ModelSpec[] {
  const listVar = (process.env[cfg.modelsEnvVar] ?? "").trim();
  const legacySingle = (process.env[`OCR_${cfg.id.toUpperCase()}_MODEL`] ?? "").trim();

  const validate = (model: ModelSpec): ModelSpec => {
    if ((model.tier !== 1 && model.tier !== 2) ||
        (model.trust !== "benchmarked" && model.trust !== "unbenchmarked")) {
      throw new Error(`OCR model "${model.id}" must register an explicit limits tier and trust tier`);
    }
    if (model.tier === 1 && model.trust !== "benchmarked") {
      throw new Error(`OCR model "${model.id}" cannot use tier 1 until it is benchmarked against paper truth`);
    }
    return model;
  };

  if (!listVar && !legacySingle) return cfg.models.map(validate);

  const byId = new Map(cfg.models.map((m) => [m.id, m]));
  const ids = (listVar ? listVar.split(",") : [legacySingle])
    .map((s) => s.trim())
    .filter(Boolean);
  if (legacySingle && listVar && !ids.includes(legacySingle)) ids.unshift(legacySingle);

  return ids.map((id) => {
    const model = byId.get(id);
    if (!model) throw new Error(`Unknown OCR model "${id}" for provider "${cfg.id}"; register limits and trust tier first`);
    return validate(model);
  });
}

export function visionProviderConfigs(): ProviderConfig[] {
  return PROVIDERS;
}

export function providerConfig(id: VisionProviderId): ProviderConfig | undefined {
  return PROVIDERS.find((p) => p.id === id);
}

