import { z } from "zod";

/**
 * Shared Zod fragment for delegation-context fields present on child workflow
 * inputs that are set by the kernel or orchestrator (never by the operator).
 *
 * All fields use `.min(1)` so an empty string set accidentally by a caller is
 * caught at schema-parse time instead of silently propagating. The field is
 * still optional from the operator perspective (omitted = standalone run).
 *
 * Usage — spread into child workflow schemas:
 *
 *   export const ChildInputSchema = z.object({
 *     // workflow-specific fields...
 *     ...PARENT_SUBJECT_FRAGMENT,
 *   });
 */

/** `parentSubject` — operator-facing subject label forwarded from the parent. */
export const PARENT_SUBJECT_FRAGMENT = {
  parentSubject: z.string().min(1).optional(),
} as const;

/** `parentRunId` — kernel-assigned parent run id for delegated children. */
export const PARENT_RUN_ID_FRAGMENT = {
  parentRunId: z.string().min(1).optional(),
} as const;

/**
 * `taskGroupId` — used by crm-doc-download and similar workflows to correlate
 * a fan-out group of delegated children under a shared logical group key.
 */
export const TASK_GROUP_ID_FRAGMENT = {
  taskGroupId: z.string().min(1).optional(),
} as const;

/** Full delegation context — combine when a workflow uses all three fields. */
export const DELEGATION_CONTEXT_FRAGMENT = {
  ...PARENT_SUBJECT_FRAGMENT,
  ...PARENT_RUN_ID_FRAGMENT,
  ...TASK_GROUP_ID_FRAGMENT,
} as const;

import { readdirSync, readFileSync, statSync } from "node:fs";
import { extname, join, resolve } from "node:path";
import ExcelJS from "exceljs";
import { rostersDir, sharepointDir } from "../../tracker/paths.js";
import { parseCsv } from "../../utils/csv.js";
import type { RosterRow } from "./match.js";

/** Roster file formats the loader can read (see `loadRoster`'s ext dispatch). */
const ROSTER_EXTENSIONS = new Set([".xlsx", ".csv"]);

export interface RosterFileRef {
  path: string;
  mtimeMs: number;
  sizeBytes: number;
  filename: string;
}

/** The operator's real tracker root — the only one whose rosters live in `data/`. */
const DEFAULT_TRACKER_DIR = ".tracker";

/**
 * Roster search dirs, in precedence order, for `trackerDir`.
 *
 * The tracker root's own dirs ALWAYS come first, and `<repo>/data/rosters` is
 * appended ONLY for the default root. That asymmetry is deliberate and load
 * bearing, not a style choice:
 *
 * `data/rosters` is operator data (the real Action History + SharePoint
 * downloads — hundreds of real employees), while a non-default tracker root
 * means the caller asked for ISOLATION (`HRAUTO_TRACKER_DIR`: the e2e lane,
 * tests, a dashboard preview seeded with synthetic fixtures). Letting a
 * cwd-anchored operator dir into an isolated root's search path breaks that
 * isolation in the worst direction: `makeCaptureFinalize` picks the FIRST
 * EXISTING dir, so `data/rosters` (always present in the repo) would win over
 * the fixture roster and silently match a synthetic capture against real
 * people. An isolated root resolves strictly within itself — no roster there is
 * "no roster", which the caller handles, rather than a wrong one.
 *
 * Legacy `<root>/rosters` + `<root>/sharepoint` stay in the list for every root
 * so older downloads still resolve.
 */
export function resolveRosterDirs(trackerDir = DEFAULT_TRACKER_DIR): string[] {
  const dirs = [
    resolve(process.cwd(), rostersDir(trackerDir)),
    resolve(process.cwd(), sharepointDir(trackerDir)),
  ];
  if (resolve(process.cwd(), trackerDir) === resolve(process.cwd(), DEFAULT_TRACKER_DIR)) {
    dirs.unshift(resolve(process.cwd(), "data", "rosters"));
  }
  return dirs;
}

/** Newest roster file (.xlsx/.csv) in `dir` by mtime, or null if dir is empty / missing / has none. */
export function findLatestRoster(dir: string): RosterFileRef | null {
  const all = listRosters(dir);
  return all[0] ?? null;
}

/** All roster files (.xlsx/.csv) in `dir`, sorted by mtime DESC. Empty array if dir missing. */
export function listRosters(dir: string): RosterFileRef[] {
  let entries: string[];
  try {
    entries = readdirSync(dir);
  } catch {
    return [];
  }
  return entries
    .filter((f) => ROSTER_EXTENSIONS.has(extname(f).toLowerCase()))
    .map((f): RosterFileRef | null => {
      const p = join(dir, f);
      try {
        const s = statSync(p);
        return { path: p, mtimeMs: s.mtimeMs, sizeBytes: s.size, filename: f };
      } catch {
        return null;
      }
    })
    .filter((x): x is RosterFileRef => x !== null)
    .sort((a, b) => b.mtimeMs - a.mtimeMs);
}

// Cache: key = `${absolutePath}:${mtimeMs}` → shared in-flight Promise.
// Rejects are evicted so transient failures (locked file, temp I/O) don't stick.
const rosterCache = new Map<string, Promise<RosterRow[]>>();

/** @internal Test isolation — clears the in-process roster cache. */
export function __resetRosterCacheForTests(): void {
  rosterCache.clear();
}

/**
 * Read a roster file (.xlsx or .csv, dispatched by extension) into a list of
 * RosterRow.
 *
 * Results are cached by `path + mtime` so repeated calls within a process
 * (e.g. OCR re-runs) skip the parse entirely when the file hasn't changed.
 *
 * The Onboarding Roster spreadsheet ships one worksheet per cohort week
 * ("July 25", "August 8", ..., "May 1") and each sheet has 0–3 preamble
 * rows (title, merged-cell decoration) above the actual header row. We
 * walk every worksheet, find the header row dynamically (first row that
 * contains a recognized column name), and concatenate matching rows.
 *
 * Recognized columns:
 *   - EID:    "UCPath ID" | "Employee ID" | "Empl ID"  (optional — rows
 *             without an EID are kept with `eid = ""` so name matching
 *             can still find them; the orchestrator falls through to
 *             eid-lookup when the resolved roster row has no EID).
 *   - Name:   "Legal Name" | "Lived Name" | "Name"  (single col), or
 *             "First Name" + "Last Name"  (split).
 *   - Address: "Street"/"Address", "City", "State", "Zip"/"Postal".
 *
 * Throws only when the file has no recognizable header in any worksheet
 * (i.e. the spreadsheet shape is fundamentally different than expected).
 */
export function loadRoster(path: string): Promise<RosterRow[]> {
  const abs = resolve(path);
  const mtimeMs = statSync(abs).mtimeMs;
  const key = `${abs}:${mtimeMs}`;
  const cached = rosterCache.get(key);
  if (cached !== undefined) return cached;
  // `async` so a synchronous parse/read throw becomes a rejection — callers
  // always get a promise, never a sync escape that dodges the cache eviction.
  const parse = extname(abs).toLowerCase() === ".csv"
    ? async () => parseCsvRosterFile(abs)
    : () => parseRosterFile(abs);
  const promise = parse().catch((err: unknown) => {
    rosterCache.delete(key);
    throw err;
  });
  rosterCache.set(key, promise);
  return promise;
}

const COLUMN_PATTERNS = {
  eid:    /^ucpath\s*id$|^empl(oyee)?\s*id$/i,
  first:  /first\s*name/i,
  last:   /last\s*name/i,
  // "Employee Name Current" is the header the Employee Action History Report
  // ships — recognize it as a name column so that report is a usable roster
  // (parity with `employee-action-history.ts`'s HEADER.name), not silently
  // skipped for having no name-bearing column.
  name:   /^legal\s*name$|^lived\s*name$|^employee\s*name(\s*current)?$|^name$/i,
  street: /^street$|^address$/i,
  city:   /^city$/i,
  state:  /^state$/i,
  zip:    /^zip$|^postal$/i,
} as const;

async function parseRosterFile(path: string): Promise<RosterRow[]> {
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.readFile(path);

  const out: RosterRow[] = [];
  let sawAnyHeader = false;

  for (const ws of wb.worksheets) {
    const headerRowNum = findHeaderRow(ws);
    if (headerRowNum === null) continue;

    const headers: string[] = [];
    ws.getRow(headerRowNum).eachCell({ includeEmpty: true }, (cell) => {
      headers.push(cellToString(cell.value).trim());
    });

    const idx = (pat: RegExp): number => headers.findIndex((h) => pat.test(h)) + 1;
    const eidCol    = idx(COLUMN_PATTERNS.eid);
    const firstCol  = idx(COLUMN_PATTERNS.first);
    const lastCol   = idx(COLUMN_PATTERNS.last);
    const nameCol   = idx(COLUMN_PATTERNS.name);
    const streetCol = idx(COLUMN_PATTERNS.street);
    const cityCol   = idx(COLUMN_PATTERNS.city);
    const stateCol  = idx(COLUMN_PATTERNS.state);
    const zipCol    = idx(COLUMN_PATTERNS.zip);

    // Sheet without any name-bearing column can't contribute usable rows.
    if (nameCol === 0 && (firstCol === 0 || lastCol === 0)) continue;
    sawAnyHeader = true;

    for (let n = headerRowNum + 1; n <= ws.rowCount; n++) {
      const row = ws.getRow(n);
      let name = nameCol > 0 ? cellToString(row.getCell(nameCol).value).trim() : "";
      if (!name && firstCol > 0 && lastCol > 0) {
        const f = cellToString(row.getCell(firstCol).value).trim();
        const l = cellToString(row.getCell(lastCol).value).trim();
        name = `${f} ${l}`.trim();
      }
      if (!name) continue;

      const eid = eidCol > 0 ? cellToString(row.getCell(eidCol).value).trim() : "";
      const street = streetCol > 0 ? cellToString(row.getCell(streetCol).value).trim() : "";
      const city = cityCol > 0 ? cellToString(row.getCell(cityCol).value).trim() : "";
      const state = stateCol > 0 ? cellToString(row.getCell(stateCol).value).trim() : "";
      const zip = zipCol > 0 ? cellToString(row.getCell(zipCol).value).trim() : "";

      out.push({
        eid,
        name,
        street: street || undefined,
        city: city || undefined,
        state: state || undefined,
        zip: zip || undefined,
      });
    }
  }

  if (!sawAnyHeader) {
    throw new Error(
      `loadRoster: no recognizable header row found in any worksheet of ${path}`,
    );
  }
  return out;
}

/**
 * Parse a `.csv` roster into RosterRow, mirroring the xlsx path: find the
 * header row dynamically (first row with a recognized column name — exports
 * often carry decorative preamble rows), resolve columns via the same
 * COLUMN_PATTERNS, keep rows with a name (EID/address optional). Throws when
 * no recognizable header exists — a fundamentally different CSV shape must
 * surface, not silently yield zero rows (fail-loud, parity with xlsx).
 */
function parseCsvRosterFile(path: string): RosterRow[] {
  const rows = parseCsv(readFileSync(path, "utf-8"));

  let headerIdx = -1;
  for (let i = 0; i < Math.min(20, rows.length); i++) {
    if (rows[i].some((cell) => HEADER_KEYWORD.test(cell.trim()))) {
      headerIdx = i;
      break;
    }
  }
  if (headerIdx === -1) {
    throw new Error(`loadRoster: no recognizable header row found in ${path}`);
  }

  const headers = rows[headerIdx].map((h) => h.trim());
  const idx = (pat: RegExp): number => headers.findIndex((h) => pat.test(h));
  const eidCol    = idx(COLUMN_PATTERNS.eid);
  const firstCol  = idx(COLUMN_PATTERNS.first);
  const lastCol   = idx(COLUMN_PATTERNS.last);
  const nameCol   = idx(COLUMN_PATTERNS.name);
  const streetCol = idx(COLUMN_PATTERNS.street);
  const cityCol   = idx(COLUMN_PATTERNS.city);
  const stateCol  = idx(COLUMN_PATTERNS.state);
  const zipCol    = idx(COLUMN_PATTERNS.zip);

  if (nameCol === -1 && (firstCol === -1 || lastCol === -1)) {
    throw new Error(
      `loadRoster: header row in ${path} has no name-bearing column (Name / Employee Name / First+Last Name)`,
    );
  }

  const cellAt = (cells: string[], col: number): string =>
    col >= 0 ? (cells[col] ?? "").trim() : "";

  const out: RosterRow[] = [];
  for (const cells of rows.slice(headerIdx + 1)) {
    let name = cellAt(cells, nameCol);
    if (!name && firstCol >= 0 && lastCol >= 0) {
      name = `${cellAt(cells, firstCol)} ${cellAt(cells, lastCol)}`.trim();
    }
    if (!name) continue;

    const street = cellAt(cells, streetCol);
    const city = cellAt(cells, cityCol);
    const state = cellAt(cells, stateCol);
    const zip = cellAt(cells, zipCol);
    out.push({
      eid: cellAt(cells, eidCol),
      name,
      street: street || undefined,
      city: city || undefined,
      state: state || undefined,
      zip: zip || undefined,
    });
  }
  return out;
}

/** Header keywords that mark a roster's real header row (shared by xlsx + csv). */
const HEADER_KEYWORD = /^(legal\s*name|lived\s*name|employee\s*name(\s*current)?|ucpath\s*id|empl(oyee)?\s*id|first\s*name|last\s*name|name)$/i;

/**
 * Find the first row in a worksheet containing a recognizable header
 * keyword. Onboarding rosters frequently have a merged-title row at the
 * top followed by a blank or near-blank row, so we scan the first 20
 * rows rather than assuming row 1.
 */
function findHeaderRow(ws: ExcelJS.Worksheet): number | null {
  const recognized = HEADER_KEYWORD;
  const limit = Math.min(20, ws.rowCount);
  for (let n = 1; n <= limit; n++) {
    const row = ws.getRow(n);
    let hit = false;
    row.eachCell({ includeEmpty: false }, (cell) => {
      if (hit) return;
      if (recognized.test(cellToString(cell.value).trim())) hit = true;
    });
    if (hit) return n;
  }
  return null;
}

/**
 * Coerce an ExcelJS cell value into a plain string. Hyperlink and
 * rich-text cells deserialize as `{text, hyperlink}` / `{richText: [...]}`
 * objects; without unwrapping them, `String(value)` produces the literal
 * text "[object Object]" — which is how the Email column rendered when
 * we first saw the SharePoint roster.
 */
function cellToString(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }
  if (value instanceof Date) return value.toISOString();
  if (typeof value === "object") {
    const v = value as Record<string, unknown>;
    if (typeof v.text === "string") return v.text;
    if (typeof v.hyperlink === "string") return v.hyperlink;
    if (Array.isArray(v.richText)) {
      return v.richText
        .map((seg) => (seg && typeof (seg as { text?: unknown }).text === "string" ? (seg as { text: string }).text : ""))
        .join("");
    }
    if (typeof v.result === "string" || typeof v.result === "number") {
      return String(v.result);
    }
    // An unrecognized cell-object shape must never collapse to
    // "[object Object]" — serialize it legibly so the bad column is
    // diagnosable at the source.
    try {
      return JSON.stringify(value) ?? "";
    } catch {
      return "[unserializable cell]";
    }
  }
  // exceljs never emits symbol/function cells; nothing readable remains.
  return "";
}

/**
 * OCR form spec for UCSD R&R Emergency Contact forms. Implements `OcrFormSpec`
 * so OCR's orchestrator runs this form-type generically.
 *
 * Replaces schemas + match logic that lived in `preview-schema.ts` + `prepare.ts`
 * (both deleted in Task 25).
 */
import { z } from "zod/v4";
import { log } from "../../../utils/log.js";
import { normalizeUcpathEmployeeId } from "../../../domain/identity/eid.js";
import {
  matchAgainstRoster,
  compareUsAddresses,
  normalizeEid,
  evaluateRosterIdentityTrust,
  shouldSkipPersonLookupForRosterTrust,
  inferEmergencyContactSameAddress,
} from "../../matching/index.js";
import type { NameSimilarityTier } from "../../matching/match.js";
import { normalizePersonNameForCompare } from "../../../domain/identity/person-name.js";
import { resolveOcrPersonDisplayName } from "../../../domain/identity/ocr-person-name.js";
import type { OcrFormSpec, LookupKind } from "../../../workflows/ocr/types.js";
import type { EmergencyContactRecord } from "../../../workflows/emergency-contact/schema.js";
import {
  DocumentTypeSchema,
  MatchStateSchema,
  VerificationSchema,
  applyDisambiguationStd,
  assertCarryForwardKindCompatible,
  isForceResearchFlagRecord,
  ocrChildItemIdPrefix,
} from "./shared.js";

// ─── Permissive OCR-pass schemas ───────────────────────────
//
// These are intentionally LOOSER than the strict downstream schemas in
// `src/workflows/emergency-contact/schema.ts`.  The vision LLM never sets
// `sameAddressAsEmployee` (it is a computed field, not on the paper form) and
// may leave `name` / `relationship` blank on a partially-filled form.  Using the
// strict schema here caused per-page `finalize()` to drop every EC record with
// the error "expected boolean, received undefined" → whole PDF appeared empty.
//
// The strict schemas still validate at the EC daemon boundary (when the approved
// input is re-parsed); strictness belongs there, not during extraction.

/**
 * Permissive address shape for the OCR pass.  `street` is nullable/optional so
 * a partially-extracted address does not drop the whole record.
 */
const PermissiveAddressOcrSchema = z.object({
  street: z.string().nullable().optional(),
  city: z.string().nullable().optional(),
  state: z.string().nullable().optional(),
  zip: z.string().nullable().optional(),
  country: z.string().nullable().optional(),
});

/**
 * Tolerant wrapper for an OCR-pass address (VL-003). The vision LLM sometimes
 * returns an address as a single STRING (a one-line "123 Main St, City, CA")
 * instead of the structured object — a strict object schema then rejected the
 * field and per-page `finalize()` dropped the WHOLE record (the operator saw
 * fewer approvable EC records than the PDF held). `z.preprocess` coerces a bare
 * string into `{ street: <string> }` so the record survives and the downstream
 * `.transform`'s `c.address.street` read (+ the strict EC daemon-boundary
 * re-parse) keep working; the operator splits the line out in review. `null` /
 * `undefined` short-circuit through `.nullable().optional()` BEFORE the
 * preprocess runs, so only an actual string is coerced. Same "never drop a
 * record over one field" precedent as the 2026-06-07 documentType/employee
 * tolerant-coercion lessons.
 */
const TolerantAddressOcrSchema = z.preprocess(
  (v) => (typeof v === "string" ? { street: v } : v),
  PermissiveAddressOcrSchema,
);

/**
 * Permissive emergency-contact shape for the OCR pass.
 *
 * Key differences from the strict `EmergencyContactSchema`:
 * - `sameAddressAsEmployee`: optional (the LLM never sets it; we default it
 *   using the same blank-address logic the strict schema's `.transform` uses).
 * - `name` / `relationship`: nullable+optional so a partially-filled form still
 *   extracts instead of being dropped.  The operator completes them in review.
 * - `address`: uses the permissive address schema so partial address data
 *   survives.
 */
const PermissiveEmergencyContactOcrSchema = z
  .object({
    name: z.string().nullable().optional(),
    relationship: z.string().nullable().optional(),
    primary: z.boolean().default(true),
    /**
     * Intentionally optional: `sameAddressAsEmployee` is a COMPUTED field never
     * present on the paper form, so the vision LLM never emits it.  We default it
     * here with the same logic as the strict schema's `.transform`: when the
     * contact has no address, force same-as-employee = true so UCPath gets the
     * employee's address rather than nothing.
     */
    sameAddressAsEmployee: z.boolean().optional(),
    address: TolerantAddressOcrSchema.nullable().optional(),
    cellPhone: z.string().nullable().optional(),
    homePhone: z.string().nullable().optional(),
    workPhone: z.string().nullable().optional(),
  })
  .transform((c) => {
    // Mirror the strict schema's blank-address rule so the downstream cast
    // (`as EmergencyContactRecord`) is always safe: when there is no contact
    // address, assume same-as-employee.
    const hasAddress = c.address != null && c.address.street != null && c.address.street.trim().length > 0;
    const sameAddress = c.sameAddressAsEmployee ?? !hasAddress;
    return {
      ...c,
      sameAddressAsEmployee: sameAddress,
      address: sameAddress ? null : c.address,
    };
  });

const PermissiveEmployeeSchema = z.object({
  name: z.string().nullable().optional(),
  firstName: z.string().nullable().optional(),
  lastName: z.string().nullable().optional(),
  employeeId: z
    .string()
    .nullable()
    .optional()
    .transform((v) => (v ?? "").trim()),
  pid: z.string().nullable().optional(),
  jobTitle: z.string().nullable().optional(),
  workLocation: z.string().nullable().optional(),
  supervisor: z.string().nullable().optional(),
  workEmail: z.string().nullable().optional(),
  personalEmail: z.string().nullable().optional(),
  homeAddress: TolerantAddressOcrSchema.nullable().optional(),
  homePhone: z.string().nullable().optional(),
  cellPhone: z.string().nullable().optional(),
});

const EC_FORM_KINDS = ["oath", "emergency-contact", "unknown"] as const;

/**
 * `formKind` tolerant coercion — mirrors `DocumentTypeSchema`'s precedent
 * (`./shared.ts`, 2026-06-04). `z.enum([...]).default("emergency-contact")`
 * only covers a MISSING (`undefined`) formKind: a PRESENT-but-unrecognized
 * string (model hallucination/typo) still FAILS `safeParse`, and per-page
 * `finalize()` drops the WHOLE record on any single-field failure — so a
 * mis-labeled record silently VANISHES from operator review instead of
 * surfacing for a human to catch (root CLAUDE.md "fail loud — no unverified
 * silent fallbacks": losing the record is worse than one wrong-looking label
 * on it). Coerce any unrecognized value to "emergency-contact" and `log.warn`
 * it so it's still visible in the run log; `undefined`/missing is the
 * ordinary "model omitted the field" case and does not warn.
 */
const EcFormKindSchema = z.preprocess((v) => {
  if (typeof v === "string" && (EC_FORM_KINDS as readonly string[]).includes(v)) return v;
  if (v !== undefined) {
    log.warn(
      `[emergency-contact] unrecognized formKind ${JSON.stringify(v)} — coercing to "emergency-contact" so the record still surfaces for review`,
    );
  }
  return "emergency-contact";
}, z.enum(EC_FORM_KINDS));

const PermissiveRecordFieldsSchema = z.object({
  formKind: EcFormKindSchema,
  sourcePage: z.number().int().positive(),
  // `z.preprocess(v => v ?? {}, …)` because the prompt tells the model to NULL
  // EC-specific fields (employee, emergencyContact) on non-EC pages (oath/unknown
  // classified inside an EC run). A bare non-nullable object would schema-drop
  // that correctly-classified wrong-form page (per-page.ts then flips it to
  // success:false → data loss). Coercing `null → {}` lets the permissive
  // sub-schemas fill their defaults, keeping downstream `record.employee.X` /
  // `record.emergencyContact.X` reads null-safe. Mirrors the 2026-06-04
  // documentType tolerant-coercion precedent.
  employee: z.preprocess((v) => v ?? {}, PermissiveEmployeeSchema),
  emergencyContact: z.preprocess((v) => v ?? {}, PermissiveEmergencyContactOcrSchema),
  notes: z.array(z.string()).default([]),
  documentType: DocumentTypeSchema,
  originallyMissing: z.array(z.string()).default([]),
});

export const PermissiveRecordSchema = PermissiveRecordFieldsSchema.transform((rec) =>
  applyEmergencyContactAddressInference(rec),
);
export type PermissiveRecord = z.infer<typeof PermissiveRecordSchema>;

/** Compare employee vs contact addresses so international / foreign contacts are not forced same-as-employee. */
function applyEmergencyContactAddressInference<T extends {
  employee: { homeAddress?: { street?: string | null; city?: string | null; state?: string | null; zip?: string | null; country?: string | null } | null };
  emergencyContact: {
    sameAddressAsEmployee: boolean;
    address?: { street?: string | null; city?: string | null; state?: string | null; zip?: string | null; country?: string | null } | null;
  };
}>(rec: T): T {
  const inferred = inferEmergencyContactSameAddress(
    rec.employee.homeAddress,
    rec.emergencyContact,
  );
  if (
    inferred.sameAddressAsEmployee === rec.emergencyContact.sameAddressAsEmployee
    && inferred.address === rec.emergencyContact.address
  ) {
    return rec;
  }
  return {
    ...rec,
    emergencyContact: {
      ...rec.emergencyContact,
      sameAddressAsEmployee: inferred.sameAddressAsEmployee,
      address: inferred.address ?? rec.emergencyContact.address,
    },
  };
}

export const OcrOutputSchema = z.array(PermissiveRecordSchema);
export type OcrOutput = z.infer<typeof OcrOutputSchema>;

